// Test-only generated bytes: no game artwork, songs or prebuilt archives.
export function silence() {
  const b=Buffer.alloc(844,128);
  b.write('RIFF');b.writeUInt32LE(b.length-8,4);b.write('WAVEfmt ',8);
  b.writeUInt32LE(16,16);b.writeUInt16LE(1,20);b.writeUInt16LE(1,22);
  b.writeUInt32LE(8000,24);b.writeUInt32LE(8000,28);b.writeUInt16LE(1,32);
  b.writeUInt16LE(8,34);b.write('data',36);b.writeUInt32LE(b.length-44,40);
  return b;
}

export function fixtureZip(entries) {
  const table=Uint32Array.from({length:256},(_,n)=>{for(let i=0;i<8;i++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
  const crc=b=>{let n=0xffffffff;for(const v of b)n=table[(n^v)&255]^(n>>>8);return(n^0xffffffff)>>>0;};
  const parts=[],directory=[];let offset=0;
  for(const [name,value]of Object.entries(entries)){
    const file=Buffer.from(name),body=Buffer.isBuffer(value)?value:Buffer.from(value),sum=crc(body);
    const local=Buffer.alloc(30),central=Buffer.alloc(46);
    local.writeUInt32LE(0x04034b50);local.writeUInt16LE(20,4);local.writeUInt16LE(0x800,6);
    local.writeUInt32LE(sum,14);local.writeUInt32LE(body.length,18);local.writeUInt32LE(body.length,22);local.writeUInt16LE(file.length,26);
    central.writeUInt32LE(0x02014b50);central.writeUInt16LE(20,4);central.writeUInt16LE(20,6);central.writeUInt16LE(0x800,8);
    central.writeUInt32LE(sum,16);central.writeUInt32LE(body.length,20);central.writeUInt32LE(body.length,24);central.writeUInt16LE(file.length,28);central.writeUInt32LE(offset,42);
    parts.push(local,file,body);directory.push(central,file);offset+=local.length+file.length+body.length;
  }
  const end=Buffer.alloc(22),size=directory.reduce((n,b)=>n+b.length,0);
  end.writeUInt32LE(0x06054b50);end.writeUInt16LE(Object.keys(entries).length,8);end.writeUInt16LE(Object.keys(entries).length,10);
  end.writeUInt32LE(size,12);end.writeUInt32LE(offset,16);
  return Buffer.concat([...parts,...directory,end]);
}
